/**
 * Our Editor — v1 data model.
 *
 * RULES
 * - Everything here is plain JSON (no DOM objects, no object URLs, no class instances).
 * - Every time value is an INTEGER number of MICROSECONDS (`Us`). Convert at the edges with
 *   `usToSec` / `secToUs` from `./time`.
 * - Units: transform.scale 1 = 100 % ("fit" size); transform.opacity 0..1; filter.intensity 0..1;
 *   adjust values use CapCut's slider ranges (see ADJUST_RANGES in ./catalog); positions are
 *   project pixels from the canvas centre (+x right, +y down); rotation in degrees.
 * - Owned by the architect. Builders do not edit this file: write requests into
 *   docs/integration-notes/<area>.md.
 */

import type { SpeedCurve } from './speedCurve';

export type Id = string;
/** Integer microseconds. */
export type Us = number;

export const SCHEMA_VERSION = 1 as const;

// ---------------------------------------------------------------- project

export type AspectRatio = '9:16' | '16:9' | '1:1' | '4:5' | '3:4';
export type Fps = 24 | 25 | 30 | 60;

export interface ProjectSettings {
  aspect: AspectRatio;
  /** Canvas size in project pixels, derived from aspect (9:16 → 1080×1920). */
  width: number;
  height: number;
  fps: Fps;
  /** Canvas background colour, CSS hex. */
  background: string;
}

export interface Marker {
  id: Id;
  time: Us;
  color: string;
  label?: string;
}

export interface Project {
  id: Id;
  name: string;
  version: typeof SCHEMA_VERSION;
  createdAt: number; // epoch ms
  updatedAt: number; // epoch ms
  settings: ProjectSettings;
  assets: Record<Id, MediaAsset>;
  /**
   * Array order = render z-order for visual tracks: index 0 is the bottom layer.
   * The single `main` track is always the first visual track. Audio tracks are not rendered
   * and may sit anywhere in the array; the timeline shows them below the main track.
   * Use `timelineRows()` from src/model/project.ts for the timeline's top-to-bottom display order.
   */
  tracks: Track[];
  markers: Marker[];
  /**
   * Compound clips / subprojects (CapCut ⌥G): nested timelines referenced by `compound` clips.
   * Optional and additive (older projects simply lack it). See src/model/compound.ts.
   */
  sequences?: Record<Id, Sequence>;
  /**
   * Nested editing (double-click a compound clip): the stack of opened sequences, outermost first.
   * While it is non-empty, `tracks` holds the tracks of the innermost opened sequence and each
   * entry keeps the tracks of the timeline it was opened from. Empty / absent = the main timeline.
   */
  focus?: SequenceFocus[];
}

/** A nested timeline (CapCut "subproject"): tracks with the same rules as the project's. */
export interface Sequence {
  id: Id;
  name: string;
  /**
   * Same rules as Project.tracks (one main track, first visual track = main). While the sequence
   * is opened for editing this is an empty placeholder: its live tracks are elsewhere (see
   * `sequenceTracks` in src/model/compound.ts).
   */
  tracks: Track[];
  /** Content length (end of the last clip), µs. Kept up to date by create / close. */
  duration: Us;
  createdAt: number;
  /** Array index each track had in the timeline it came from (ungroup restores them there). */
  origin?: Record<Id, number>;
}

export interface SequenceFocus {
  sequenceId: Id;
  /** The tracks of the timeline this sequence was opened from (restored on close). */
  parentTracks: Track[];
}

// ---------------------------------------------------------------- media

export type MediaKind = 'video' | 'audio' | 'image';

export interface MediaAsset {
  id: Id;
  kind: MediaKind;
  name: string;
  mime: string;
  size: number; // bytes
  /** Source duration. Images: 0 (unbounded). */
  duration: Us;
  width?: number;
  height?: number;
  hasAudio?: boolean;
  /** Key of the File/Blob in the IndexedDB `blobs` store. */
  blobKey: Id;
  /** Set at load time when the blob could not be found ("Media lost"). Not persisted meaningfully. */
  missing?: boolean;
}

// ---------------------------------------------------------------- tracks

/** main = the magnetic main video track; overlay = picture-in-picture video/image track. */
export type TrackKind = 'main' | 'overlay' | 'audio' | 'text';

export interface Track {
  id: Id;
  kind: TrackKind;
  name: string;
  locked: boolean;
  /** Eye icon: hides the track's pictures from player and export (audio still plays). */
  hidden: boolean;
  /** Speaker icon: mutes the track's audio. */
  muted: boolean;
  /** Sorted by start, never overlapping. Main track with magnet ON: packed from 0 with no gaps. */
  clips: Clip[];
  /** Transitions between adjacent clips of THIS track. */
  transitions: Transition[];
}

// ---------------------------------------------------------------- clip props

export interface Transform {
  /** 1 = 100 % = media "contained" (fit) inside the canvas. Range 0.01..4 (1 %..400 %). */
  scale: number;
  /** Offset of the clip centre from the canvas centre, project px. */
  x: number;
  y: number;
  /** Degrees, clockwise. */
  rotation: number;
  /** 0..1 */
  opacity: number;
  /** Mirror (toolbar). */
  flipH: boolean;
  flipV: boolean;
  /**
   * CapCut "Uniform scale" switch (Video › Basic › Transform). true: `scale` scales both axes.
   * false: `scaleX` / `scaleY` (same units and range as `scale`) scale width and height separately.
   */
  uniformScale: boolean;
  scaleX: number;
  scaleY: number;
}

// ---------------------------------------------------------------- Video tab (mask, chroma key, canvas)

/** Video › Mask shapes (CapCut's non-AI masks). 'none' = no mask. */
export type MaskShape = 'none' | 'linear' | 'mirror' | 'circle' | 'rectangle' | 'heart' | 'star';

/**
 * Video › Mask. Geometry is relative to the clip's own picture (its fitted, cropped box at
 * scale 1), so the mask moves, scales and rotates with the clip:
 * x / y = offset of the mask centre from the picture centre, as fractions of the picture
 * width / height; width / height = mask size as fractions of the picture width / height.
 */
export interface ClipMask {
  shape: MaskShape;
  x: number;
  y: number;
  /** Degrees, clockwise, on top of the clip rotation. */
  rotation: number;
  width: number;
  height: number;
  /** 0..100: soft edge. */
  feather: number;
  /** 0..100: rectangle corner radius (100 = half the shorter side). */
  roundCorners: number;
  /** Show the outside of the shape instead of the inside. */
  invert: boolean;
}

/** Video › Remove BG › Chroma key (non-AI colour key). */
export interface ChromaKey {
  enabled: boolean;
  /** Key colour, CSS hex. */
  color: string;
  /** 0..100: how far from the key colour (in chroma) a pixel is still removed. */
  intensity: number;
  /** 0..100: softness of the key edge (partially transparent band). */
  shadow: number;
}

export type CanvasBackgroundType = 'none' | 'color' | 'blur' | 'image';

/** Video › Basic › Canvas: what fills the frame around a main-track clip. */
export interface CanvasBackground {
  type: CanvasBackgroundType;
  /** type 'color': CSS hex. */
  color: string;
  /** type 'blur': level 1..4 (CapCut's four blur tiles). */
  blur: number;
  /** type 'image': an image asset of the project (null = not chosen yet). */
  assetId: Id | null;
}

/** Crop rectangle as fractions of the source (0 = no crop on that side). v1: model + render only, UI is v2. */
export interface Crop {
  left: number;
  top: number;
  right: number;
  bottom: number;
}

export type BlendMode =
  | 'normal'
  | 'multiply'
  | 'screen'
  | 'overlay'
  | 'darken'
  | 'lighten'
  | 'hard-light'
  | 'soft-light'
  | 'linear-burn'
  | 'color-burn'
  | 'color-dodge';

/** Fill channel: which source channel is copied to both outputs. */
export type FillChannel = 'left' | 'right';

/** Non-AI voice filters (Audio › Voice changer). DSP recipes live in src/audio/dsp.ts. */
export type VoiceFilterId =
  | 'chipmunk'
  | 'high'
  | 'low'
  | 'deep'
  | 'robot'
  | 'electronic'
  | 'echo'
  | 'megaphone'
  | 'distorted'
  | 'vinyl'
  | 'hall'
  // spaces (added 26 Oct 2026)
  | 'room'
  | 'studio'
  | 'tiled'
  | 'stone'
  | 'cathedral'
  | 'outdoor'
  | 'distant'
  | 'next-room'
  // eras & devices
  | 'phone'
  | 'walkie'
  | 'radio-old'
  | 'gramophone'
  // characters
  | 'broadcast'
  | 'intimate'
  | 'inner-voice'
  | 'memory'
  | 'underwater';

/**
 * Audio › Voice changer › Mixer: a hand-tuned channel strip, like a mixing desk. Applied after the
 * voice filter, in this order: low cut → high cut → EQ → compressor → warmth → delay → reverb →
 * output. Each section has its own switch. DSP: src/audio/dsp.ts (buildMixer). Added 26 Oct 2026.
 */
export interface VoiceMixer {
  /** High-pass, Hz (0 = off). */
  lowCut: number;
  /** Low-pass, Hz (0 = off). */
  highCut: number;
  eq: { on: boolean; lowFreq: number; lowGain: number; midFreq: number; midGain: number; midQ: number; highFreq: number; highGain: number };
  /** threshold / makeup dB, attack / release ms, ratio n:1. */
  comp: { on: boolean; threshold: number; ratio: number; attack: number; release: number; makeup: number };
  /** Tape-style saturation: drive 0..100, mix 0..100 %. */
  warmth: { on: boolean; drive: number; mix: number };
  /** time ms, feedback / mix %. */
  delay: { on: boolean; time: number; feedback: number; mix: number };
  /** decay s, pre-delay ms, damping 0..100 (darker tail), mix %. */
  reverb: { on: boolean; decay: number; predelay: number; damping: number; mix: number };
  /** Output gain, dB. */
  output: number;
}

/**
 * Voice isolation (DSP, not AI) — CapCut's "Isolate voice" with a signal-processing engine
 * (src/audio/isolateCore.ts). 'isolate' keeps the voice (noise-profile Wiener suppression +
 * 100 Hz–8 kHz emphasis + gentle gate); 'remove' keeps the background (approximate: mid/side
 * centre cancellation in the speech band).
 */
export type VoiceIsolationMode = 'isolate' | 'remove';

export interface VoiceIsolation {
  mode: VoiceIsolationMode;
  /** 0..100 (UI "Strength"). */
  strength: number;
}

export interface VoiceFilter {
  id: VoiceFilterId;
  /** 0..100 (UI "Strength"). */
  strength: number;
}

/**
 * A volume keyframe. `src` is the clip's source position (µs, inPoint + source offset — the same
 * frame as `inPoint`), so keys stay on their sound through trims, splits and speed changes.
 */
export interface VolumeKey {
  src: Us;
  /** -60..+20 dB. */
  db: number;
}

export interface AudioProps {
  /** -60..+20 dB. -60 is treated as silence. Ignored while `volumeKeys` has keys. */
  volumeDb: number;
  /**
   * Volume keyframes, sorted by `src`. When present (≥ 1) they replace `volumeDb`: the volume is
   * interpolated linearly in dB between keys and held flat before the first / after the last.
   * Absent = no keyframes. Added 25 Oct 2026 (src/model/volumeKeys.ts).
   */
  volumeKeys?: VolumeKey[];
  fadeIn: Us;
  fadeOut: Us;
  /** Per-clip mute (the Basic section checkbox in Audio › Basic). */
  muted: boolean;
  /**
   * Normalize loudness: the clip's source span is measured (ITU-R BS.1770 integrated loudness)
   * and a gain brings it to NORMALIZE_TARGET_LUFS (src/audio/loudness.ts). Volume dB applies on top.
   * Added after v1 (migrateProject fills it).
   */
  normalize: boolean;
  /** Reduce noise — DSP high-pass + adaptive noise gate (not AI). Added after v1. */
  reduceNoise: boolean;
  /** Fill channel; null = off. Added after v1. */
  fillChannel: FillChannel | null;
  /** Voice changer filter; null = None. Added after v1. */
  voiceFilter: VoiceFilter | null;
  /** Voice isolation (DSP); null = off. Added 20 Oct 2026 (migrateAudioProps fills it). */
  voiceIsolation: VoiceIsolation | null;
  /** Voice changer › Mixer channel strip; absent / null = off. Added 26 Oct 2026. */
  mixer?: VoiceMixer | null;
}

/**
 * Animation id from the catalogue in src/engine/animations.ts (ids are unique per phase:
 * the In "fade" is Fade In, the Out "fade" is Fade Out). The v1 ids ('fade', 'zoom-in',
 * 'zoom-out', 'slide-left/right/up/down', 'rotate', 'blur') are all still in the catalogue.
 * An unknown id renders as no animation.
 */
export type AnimationType = string;

export interface ClipAnimation {
  type: AnimationType;
  /**
   * In / Out / Combo: length of the animation window, µs (In at the clip start, Out at the end,
   * Combo from the clip start). Loop: length of ONE cycle, µs (the loop repeats over the clip).
   */
  duration: Us;
}

/** Animation slots of a visual clip (CapCut: video/image In · Out · Combo, text In · Out · Loop). */
export type AnimationSlot = 'in' | 'out' | 'combo' | 'loop';

export type FilterId =
  | 'mono'
  | 'noir'
  | 'sepia'
  | 'vintage'
  | 'warm'
  | 'cool'
  | 'vivid'
  | 'fade'
  | 'cinematic'
  | 'retro';

export interface FilterRef {
  id: FilterId;
  /** 0..1 (UI shows 0..100). */
  intensity: number;
}

/**
 * Adjust › Basic › Adjust. All 0 = neutral. Ranges in ADJUST_RANGES (./catalog).
 * whites / blacks / brilliance / clarity / grain were added after v1 (migrateProject fills 0).
 */
export interface Adjust {
  // Color
  temperature: number; // -50..50 (blue ↔ yellow)
  tint: number; // -50..50 (green ↔ magenta)
  saturation: number; // -50..50 (-50 = grey)
  // Lightness
  exposure: number; // -50..50 (±1.5 EV, linear light)
  brightness: number; // -50..50 (mid-tone gamma)
  contrast: number; // -50..50
  highlights: number; // -50..50
  shadows: number; // -50..50
  whites: number; // -50..50
  blacks: number; // -50..50
  brilliance: number; // -50..50
  // Effects
  sharpen: number; // 0..100
  clarity: number; // 0..100
  /** CapCut "Particles" (film grain). */
  grain: number; // 0..100
  fade: number; // 0..100
  vignette: number; // 0..100
}

// ---------------------------------------------------------------- colour grade (Adjust tab)

/** Adjust › Basic › LUT. The .cube file lives in the browser-wide LUT library (IndexedDB). */
export interface LutSettings {
  /** Section checkbox. */
  enabled: boolean;
  /** Id in the LUT library; null = "None". */
  lutId: Id | null;
  /** File name shown when the LUT is missing from this browser. */
  name: string;
  /** 0..1 (UI 0..100). */
  intensity: number;
  /** Keeps skin hues closer to the original (non-AI hue/saturation key). */
  protectSkin: boolean;
}

export type HslColor = 'red' | 'orange' | 'yellow' | 'green' | 'cyan' | 'blue' | 'purple' | 'magenta';

/** One HSL colour range. Each -100..100, 0 = neutral. */
export interface HslBand {
  hue: number;
  saturation: number;
  lightness: number;
}

export interface HslSettings {
  enabled: boolean;
  bands: Record<HslColor, HslBand>;
}

/** Curve control point, both axes 0..1 (input → output). Sorted by x; first x = 0, last x = 1. */
export interface CurvePoint {
  x: number;
  y: number;
}

export type CurveChannel = 'master' | 'red' | 'green' | 'blue';

export interface CurvesSettings {
  enabled: boolean;
  /** Master = CapCut's white "Luma"/RGB curve, applied before the per-channel curves. */
  master: CurvePoint[];
  red: CurvePoint[];
  green: CurvePoint[];
  blue: CurvePoint[];
}

/** A colour wheel: puck position in the unit disc (x right, y up) + its luminance slider -100..100. */
export interface WheelValue {
  x: number;
  y: number;
  luma: number;
}

export type WheelId = 'lift' | 'gamma' | 'gain' | 'offset';

export interface WheelsSettings {
  enabled: boolean;
  lift: WheelValue;
  gamma: WheelValue;
  gain: WheelValue;
  offset: WheelValue;
}

export type AdjustMaskShape = 'none' | 'linear' | 'mirror' | 'circle' | 'rectangle';

/** Adjust › Mask: limits the whole colour adjustment to a shape. Clip-local units. */
export interface AdjustMask {
  shape: AdjustMaskShape;
  /** Centre offset as fractions of the clip box (0,0 = centre; ±0.5 = edge). */
  x: number;
  y: number;
  /** Size as fractions of the clip box width / height (circle, rectangle, mirror band). */
  width: number;
  height: number;
  /** Degrees, clockwise. */
  rotation: number;
  /** 0..100 (soft edge). */
  feather: number;
  /** Rectangle corner roundness 0..100. */
  roundness: number;
  invert: boolean;
}

/** Everything in the Adjust tab besides Basic › Adjust (`adjust`) and the Filter look. */
export interface ColorGrade {
  lut: LutSettings;
  hsl: HslSettings;
  curves: CurvesSettings;
  wheels: WheelsSettings;
  mask: AdjustMask;
  /** Adjust › Color (DaVinci-style page, added by color-grade; migrateColorPage fills it). */
  color: import('./colorPage').ColorPage;
}

export type TextAlign = 'left' | 'center' | 'right';

export interface TextStyle {
  content: string;
  fontFamily: string;
  /** Project px. */
  fontSize: number;
  color: string;
  bold: boolean;
  italic: boolean;
  underline: boolean;
  align: TextAlign;
  /** Multiplier of fontSize. */
  lineHeight: number;
  /** Extra px between characters. */
  letterSpacing: number;
  stroke: { enabled: boolean; color: string; width: number };
  background: { enabled: boolean; color: string; opacity: number };
  shadow: { enabled: boolean; color: string; blur: number; offsetX: number; offsetY: number };
}

// ---------------------------------------------------------------- clips

export type ClipType = 'video' | 'image' | 'audio' | 'text' | 'compound';

interface ClipBase {
  id: Id;
  type: ClipType;
  trackId: Id;
  /** Display name (defaults to asset name / text content). */
  name: string;
  /** Timeline position. */
  start: Us;
  /** Length on the timeline (already divided by speed). */
  duration: Us;
  /** Disabled clips stay on the timeline but are neither drawn nor heard. */
  disabled: boolean;
}

/** Fields shared by every clip that draws pictures. */
export interface VisualFields {
  transform: Transform;
  crop: Crop;
  blend: BlendMode;
  /** Blend section checkbox. false = draw as Normal at 100 % opacity (values kept). */
  blendEnabled: boolean;
  animationIn: ClipAnimation | null;
  animationOut: ClipAnimation | null;
  /** Combo (video/image): one in-and-back motion from the clip start. Exclusive with In/Out. */
  animationCombo: ClipAnimation | null;
  /** Loop (text): repeats every `duration` µs for the whole clip; combines with In/Out. */
  animationLoop: ClipAnimation | null;
  filter: FilterRef | null;
  adjust: Adjust;
  /** Adjust section checkbox. false = the Adjust sliders are ignored (values kept; filter still applies). */
  adjustEnabled: boolean;
  /** Adjust tab: LUT, HSL, Curves, Color wheel, Mask. */
  grade: ColorGrade;
}

/** Fields shared by clips that read a time range of a media asset. */
export interface TimedMediaFields {
  assetId: Id;
  /**
   * Source in-point. The source span used is [inPoint, inPoint + sourceSpan(clip)], where
   * sourceSpan = duration × speed (Standard) or duration × mean(curve) (Curve). See model/time.ts.
   */
  inPoint: Us;
  /** Standard speed, 0.1..100. Ignored (kept at 1) while `speedCurve` is set. */
  speed: number;
  /**
   * Speed › Curve: speed over the clip's normalised output time (0.1x..10x), or null for
   * Standard speed. Added after v1; `migrateProject` fills null in older projects.
   */
  speedCurve: SpeedCurve | null;
  /** CapCut "Change audio pitch" = !preservePitch. Default true (pitch preserved). */
  preservePitch: boolean;
  /**
   * Edit › Reverse: the clip plays its source backwards. While true, `inPoint` is measured in the
   * REVERSED media (from its end): the clip reads reversed-media time [inPoint, inPoint + span],
   * i.e. real media time (D − inPoint − span, D − inPoint], D = asset.duration. Every timeline op
   * (trim, split, speed, fit-to-media) therefore works unchanged; only the consumers that read
   * media time map back through `mediaTimeOf` (model/time.ts). Added after v1 (migrateProject
   * fills false).
   */
  reversed: boolean;
}

/** Video-tab fields of clips that show a media picture (video, image). */
export interface MediaVisualFields {
  mask: ClipMask;
  chroma: ChromaKey;
  /** Only used on the main track (CapCut shows Canvas for main-track clips). */
  canvas: CanvasBackground;
}

export interface VideoClip extends ClipBase, VisualFields, MediaVisualFields, TimedMediaFields {
  type: 'video';
  audio: AudioProps;
  /**
   * "Extract audio" (⌘⇧S) link: the same id is set on this video clip and on the audio clip made
   * from it, and the video's own audio is muted. Splitting either side copies the id, so every
   * piece stays linked. "Restore audio" removes the linked audio clips, unmutes the linked video
   * clips and clears the id. Optional and additive (older projects simply lack it).
   */
  audioLink?: Id;
}

export interface ImageClip extends ClipBase, VisualFields, MediaVisualFields {
  type: 'image';
  assetId: Id;
}

export interface AudioClip extends ClipBase, TimedMediaFields {
  type: 'audio';
  audio: AudioProps;
  /** See VideoClip.audioLink: set on audio clips made by "Extract audio". */
  audioLink?: Id;
}

export interface TextClip extends ClipBase, VisualFields {
  type: 'text';
  text: TextStyle;
}

/**
 * Compound clip (CapCut "Create compound clip", ⌥G): shows the sequence `sequenceId` from
 * `inPoint` on, for `duration`. Its transform / opacity / blend / animations / colour wrap the
 * nested picture as one layer; the nested audio plays as if the clips were on the timeline.
 */
export interface CompoundClip extends ClipBase, VisualFields {
  type: 'compound';
  sequenceId: Id;
  /** Offset into the sequence, µs (trimming the clip's start moves it). */
  inPoint: Us;
}

export type Clip = VideoClip | ImageClip | AudioClip | TextClip | CompoundClip;
export type VisualClip = VideoClip | ImageClip | TextClip | CompoundClip;
export type MediaClip = VideoClip | ImageClip | AudioClip;
export type TimedClip = VideoClip | AudioClip;

/**
 * Generic patch for `updateClip`. Nested objects are merged one level deep.
 * A field is applied only if the clip has it (e.g. `text` on a video clip is ignored).
 * Timing (start, duration, inPoint, speed, trackId) is NOT patchable here — use the dedicated
 * store actions (moveClip, trimStart, trimEnd, setSpeed, setDuration).
 */
export interface ClipPatch {
  name?: string;
  disabled?: boolean;
  transform?: Partial<Transform>;
  crop?: Partial<Crop>;
  blend?: BlendMode;
  blendEnabled?: boolean;
  adjustEnabled?: boolean;
  animationIn?: ClipAnimation | null;
  animationOut?: ClipAnimation | null;
  animationCombo?: ClipAnimation | null;
  animationLoop?: ClipAnimation | null;
  filter?: FilterRef | null;
  adjust?: Partial<Adjust>;
  mask?: Partial<ClipMask>;
  chroma?: Partial<ChromaKey>;
  canvas?: Partial<CanvasBackground>;
  /** Merged one level deep: each given section (lut, hsl, curves, wheels, mask) replaces the old one. */
  grade?: Partial<ColorGrade>;
  audio?: Partial<AudioProps>;
  text?: Partial<Omit<TextStyle, 'stroke' | 'background' | 'shadow'>> & {
    stroke?: Partial<TextStyle['stroke']>;
    background?: Partial<TextStyle['background']>;
    shadow?: Partial<TextStyle['shadow']>;
  };
  preservePitch?: boolean;
}

// ---------------------------------------------------------------- transitions

export type TransitionType =
  | 'mix'
  | 'fade-black'
  | 'fade-white'
  | 'slide-left'
  | 'slide-right'
  | 'slide-up'
  | 'slide-down'
  | 'wipe-left'
  | 'wipe-right'
  | 'zoom'
  | 'blur';

/**
 * A transition sits on the cut between two ADJACENT clips of the same track
 * (from.start + from.duration === to.start). It is centred on the cut:
 * window = [cut - duration/2, cut + duration/2). Timeline length does not change; when a
 * source runs out the renderer holds the edge frame. Max duration = half the shorter clip.
 */
export interface Transition {
  id: Id;
  type: TransitionType;
  fromClipId: Id;
  toClipId: Id;
  duration: Us;
}
